SERVICIOS:
AuthService → login, logout, token
DashboardService → KPIs, resumen
EmployeeService → CRUD empleados
ReportService → datos de reportes

RUTAS CON LAZY LOADING:
export const routes: Routes = [
  { path: "", redirectTo: "dashboard", pathMatch: "full" },
  {
    path: "auth",
    loadComponent: () => import("./features/auth/auth.layout")
      .then(m => m.AuthLayout),
    children: [
      { path: "login", loadComponent: () => import("./features/auth/login")
        .then(m => m.LoginComponent) },
      { path: "register", loadComponent: () => import("./features/auth/register")
        .then(m => m.RegisterComponent) }
    ]
  },
  {
    path: "dashboard",
    canActivate: [authGuard],
    loadComponent: () => import("./features/dashboard/dashboard.layout")
      .then(m => m.DashboardLayout),
    children: [
      { path: "", loadComponent: () => import("./features/dashboard/home")
        .then(m => m.DashboardHomeComponent) },
      { path: "employees", loadComponent: () => import("./features/employees/list")
        .then(m => m.EmployeeListComponent) },
      { path: "employees/:id", loadComponent: () => import("./features/employees/detail")
        .then(m => m.EmployeeDetailComponent) },
      { path: "reports", loadComponent: () => import("./features/reports")
        .then(m => m.ReportsComponent) },
      { path: "settings", loadComponent: () => import("./features/settings")
        .then(m => m.SettingsComponent) }
    ]
  },
  { path: "**", redirectTo: "dashboard" }
];

AUTH FEATURE:
• LoginComponent → formulario reactivo + validación
• RegisterComponent → formulario con confirmación
• AuthFacade → orquesta AuthService + routing

EMPLOYEES FEATURE:
• EmployeeListComponent → DataTable con filtros
• EmployeeDetailComponent → formulario edición
• EmployeeFormComponent → crear/editar reutilizable

PATRÓN FACADE:
@Injectable({ providedIn: "root" })
export class EmployeeFacade {
  private employeeService = inject(EmployeeService);
  private router = inject(Router);

  employees$ = this.employeeService.employees$;
  loading$ = this.employeeService.loading$;

  loadEmployees(): void {
    this.employeeService.loadAll();
  }

  createEmployee(data: Omit<Employee, "id">): void {
    this.employeeService.create(data).subscribe({
      next: () => this.router.navigate(["/dashboard/employees"]),
      error: (err) => this.notificationService.showError(err.message)
    });
  }
}

REPORTS FEATURE (Chart.js / ng2-charts):
@Component({
  standalone: true,
  imports: [NgChartsModule],
  template: `
    <canvas baseChart
      [data]="chartData"
      [labels]="chartLabels"
      [type]="'bar'" [options]="chartOptions">
    </canvas>
  `
})
export class SalesChartComponent implements OnInit {
  private reportService = inject(ReportService);
  chartData: ChartConfiguration["data"] = { labels: [], datasets: [] };

  ngOnInit(): void {
    this.reportService.getSalesReport().subscribe(data => {
      this.chartData = {
        labels: data.map(d => d.label),
        datasets: [{
          label: "Ventas",
          data: data.map(d => d.value),
          backgroundColor: "#6366f1"
        }]
      };
    });
  }
}

