def reintentar(max_intentos=3, delay=1):
    def decorador(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(max_intentos):
                try: return func(*args, **kwargs)
                except Exception as e:
                    if i == max_intentos - 1: raise
                    time.sleep(delay)
        return wrapper
    return decorador

@reintentar(max_intentos=5, delay=2)
