    private readonly Mock<ICalificacionRepository> _repoMock;
    private readonly CalificacionService _service;

    public CalificacionServiceTests()
    {
        _repoMock = new Mock<ICalificacionRepository>();
        _service = new CalificacionService(_repoMock.Object);
    }

    [Fact]
    public async Task Registrar_CalculaFinalComoPromedio()
    {
        var dto = new CrearCalificacionDTO(1, 1, 8, 9, 7);
        _repoMock.Setup(r => r.AddAsync(It.IsAny<Calificacion>()))
            .ReturnsAsync((Calificacion c) => { c.Id = 1; return c; });

        var result = await _service.RegistrarAsync(dto);

        Assert.Equal(8.0, result.Final); // (8+9+7)/3 = 8
        Assert.Equal("Aprobado", result.Estatus);
    }

    [Fact]
    public async Task Registrar_ConParcialInvalido_LanzaExcepcion()
    {
        var dto = new CrearCalificacionDTO(1, 1, 11, 9, 7);
        await Assert.ThrowsAsync<ArgumentException>(() => _service.RegistrarAsync(dto));
    }
}

