DECLARE
  CURSOR c_empleados IS
    SELECT id, nombre, salario FROM Empleado WHERE salario < 3000
    FOR UPDATE OF salario;
  v_count NUMBER := 0;
BEGIN
  FOR emp IN c_empleados LOOP
    UPDATE Empleado SET salario = salario * 1.10
    WHERE CURRENT OF c_empleados;

    INSERT INTO AuditoriaAumentos(empleado_id, salario_anterior, salario_nuevo, fecha)
    VALUES(emp.id, emp.salario, emp.salario * 1.10, SYSDATE);

    v_count := v_count + 1;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Empleados actualizados: ' || v_count);
  COMMIT;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('No se encontraron empleados');
  WHEN OTHERS THEN
    ROLLBACK;
    DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);
END;

