interface IUserRepository { save(user); findByCredentials(u,p); }
class MySQLUserRepo implements IUserRepository { /* MySQL */ }
class MongoUserRepo implements IUserRepository { /* Mongo */ }

class EmailService { send(user, template); }
class PDFService { generate(user); }
class PasswordValidator { validate(pwd); }

class AuthService {
  constructor(private repo: IUserRepository, private validator: PasswordValidator) {}
  login(user, pass) {
    if (this.validator.validate(pass)) return this.repo.findByCredentials(user, pass);
  }
