function Contador() {
  const [count, setCount] = useState(0);

  const incrementar = () => setCount(prev => prev + 1);
  const decrementar = () => setCount(prev => Math.max(0, prev - 1));
  const resetear = () => setCount(0);

  const getMensaje = () => {
    if (count === 0) return "Inicio — ¡empieza a contar!";
    if (count <= 5) return "Contando poco a poco";
    if (count <= 10) return "¡Vas bien!";
    return "¡Eres imparable!";
  };

  return (
    <div className="contador">
      <h2>Contador: {count}</h2>
      <p>{getMensaje()}</p>
      <div className="contador__botones">
        <button onClick={decrementar} disabled={count === 0}>-</button>
        <button onClick={resetear}>Reset</button>
        <button onClick={incrementar}>+</button>
      </div>
    </div>
  );
}

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

type Filtro = "todas" | "activas" | "completadas";

function TodoList() {
  const [tareas, setTareas] = useState<Todo[]>([]);
  const [input, setInput] = useState("");
  const [filtro, setFiltro] = useState<Filtro>("todas");

  const agregar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;
    setTareas(prev => [...prev, { id: Date.now(), text: input.trim(), completed: false }]);
    setInput("");
  };

  const toggle = (id: number) => {
    setTareas(prev => prev.map(t =>
      t.id === id ? { ...t, completed: !t.completed } : t
    ));
  };

  const eliminar = (id: number) => {
    setTareas(prev => prev.filter(t => t.id !== id));
  };

  const tareasFiltradas = tareas.filter(t => {
    if (filtro === "activas") return !t.completed;
    if (filtro === "completadas") return t.completed;
    return true;
  });

  return (
    <div>
      <form onSubmit={agregar}>
        <input value={input} onChange={e => setInput(e.target.value)} placeholder="Nueva tarea" />
        <button type="submit">Agregar</button>
      </form>
      <div>
        {(["todas", "activas", "completadas"] as Filtro[]).map(f => (
          <button key={f} onClick={() => setFiltro(f)}
            style={{ fontWeight: filtro === f ? "bold" : "normal" }}>
            {f}
          </button>
        ))}
      </div>
      <ul>
        {tareasFiltradas.map(t => (
          <li key={t.id}>
            <input type="checkbox" checked={t.completed} onChange={() => toggle(t.id)} />
            <span style={{ textDecoration: t.completed ? "line-through" : "none" }}>{t.text}</span>
            <button onClick={() => eliminar(t.id)}>✕</button>
          </li>
        ))}
      </ul>
      <p>{tareas.filter(t => !t.completed).length} tareas pendientes</p>
    </div>
  );
}

import { useState, useEffect } from "react";

interface UseFetchResult<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
}

function useFetch<T>(url: string): UseFetchResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(url, { signal: controller.signal })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(json => {
        setData(json);
        setLoading(false);
      })
      .catch(err => {
        if (err.name !== "AbortError") {
          setError(err.message);
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [url]);

  return { data, loading, error };
}

