function Temporizador() {
  const [tiempo, setTiempo] = useState(0);
  const [activo, setActivo] = useState(false);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (activo) {
      intervalRef.current = setInterval(() => {
        setTiempo(prev => prev + 1);
      }, 1000);
    } else if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [activo]);

  const formatear = (s: number) => {
    const min = Math.floor(s / 60).toString().padStart(2, "0");
    const sec = (s % 60).toString().padStart(2, "0");
    return `${min}:${sec}`;
  };

  const resetear = () => {
    setActivo(false);
    setTiempo(0);
  };

  return (
    <div>
      <h2>{formatear(tiempo)}</h2>
      <button onClick={() => setActivo(!activo)}>
        {activo ? "Pausar" : "Iniciar"}
      </button>
      <button onClick={resetear}>Resetear</button>
    </div>
  );
}

import { createContext, useContext, useState, ReactNode } from "react";

interface User {
  email: string;
  nombre: string;
}

interface AuthState {
  user: User | null;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthState | null>(null);

function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);

  const login = async (email: string, _password: string) => {
    // Simulación de API
    await new Promise(r => setTimeout(r, 500));
    setUser({ email, nombre: email.split("@")[0] });
  };

  const logout = () => setUser(null);

  return (
    <AuthContext.Provider value={{ user, login, logout, isAuthenticated: !!user }}>
      {children}
    </AuthContext.Provider>
  );
}

function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth requiere AuthProvider");
  return ctx;
}

function ProtectedRoute({ children }: { children: ReactNode }) {
  const { isAuthenticated } = useAuth();
  if (!isAuthenticated) return <p>Debes iniciar sesión</p>;
  return <>{children}</>;
}

import { createContext, useContext, useReducer, ReactNode } from "react";

interface Producto {
  id: number;
  nombre: string;
  precio: number;
}

interface CartItem extends Producto {
  cantidad: number;
}

type CartAction =
  | { type: "ADD"; producto: Producto }
  | { type: "REMOVE"; id: number }
  | { type: "UPDATE_QTY"; id: number; cantidad: number }
  | { type: "CLEAR" };

function cartReducer(state: CartItem[], action: CartAction): CartItem[] {
  switch (action.type) {
    case "ADD": {
      const exists = state.find(i => i.id === action.producto.id);
      if (exists) return state.map(i =>
        i.id === action.producto.id ? { ...i, cantidad: i.cantidad + 1 } : i
      );
      return [...state, { ...action.producto, cantidad: 1 }];
    }
    case "REMOVE": return state.filter(i => i.id !== action.id);
    case "UPDATE_QTY": return state.map(i =>
      i.id === action.id ? { ...i, cantidad: Math.max(1, action.cantidad) } : i
    );
    case "CLEAR": return [];
  }
}

interface CartState {
  items: CartItem[];
  agregar: (p: Producto) => void;
  eliminar: (id: number) => void;
  actualizarQty: (id: number, qty: number) => void;
  vaciar: () => void;
  total: number;
  totalItems: number;
}

const CartContext = createContext<CartState | null>(null);

function CartProvider({ children }: { children: ReactNode }) {
  const [items, dispatch] = useReducer(cartReducer, []);

  const agregar = (producto: Producto) => dispatch({ type: "ADD", producto });
  const eliminar = (id: number) => dispatch({ type: "REMOVE", id });
  const actualizarQty = (id: number, cantidad: number) => dispatch({ type: "UPDATE_QTY", id, cantidad });
  const vaciar = () => dispatch({ type: "CLEAR" });
  const total = items.reduce((sum, i) => sum + i.precio * i.cantidad, 0);
  const totalItems = items.reduce((sum, i) => sum + i.cantidad, 0);

  return (
    <CartContext.Provider value={{ items, agregar, eliminar, actualizarQty, vaciar, total, totalItems }}>
      {children}
    </CartContext.Provider>
  );
}

function useCart() {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error("useCart requiere CartProvider");
  return ctx;
}

