import { createContext, useContext, useReducer, ReactNode } from 'react';

interface CartItem { id: number; nombre: string; precio: number; cantidad: number; }
type CartAction =
  | { type: 'ADD'; item: Omit<CartItem, 'cantidad'> }
  | { type: 'REMOVE'; id: number }
  | { type: 'UPDATE_QTY'; id: number; cantidad: number }
  | { type: 'CLEAR' };

function cartReducer(state: CartItem[], action: CartAction): CartItem[] {
  switch (action.type) {
    case 'ADD': {
      const exists = state.find(i => i.id === action.item.id);
      if (exists) return state.map(i => i.id === action.item.id ? { ...i, cantidad: i.cantidad + 1 } : i);
      return [...state, { ...action.item, cantidad: 1 }];
    }
    case 'REMOVE': return state.filter(i => i.id !== action.id);
    case 'UPDATE_QTY': return state.map(i => i.id === action.id ? { ...i, cantidad: Math.max(1, action.cantidad) } : i);
    case 'CLEAR': return [];
  }
}

const CartContext = createContext<{ items: CartItem[]; dispatch: React.Dispatch<CartAction>; total: number; totalItems: number } | null>(null);

function CartProvider({ children }: { children: ReactNode }) {
  const [items, dispatch] = useReducer(cartReducer, []);
  const total = items.reduce((sum, i) => sum + i.precio * i.cantidad, 0);
  const totalItems = items.reduce((sum, i) => sum + i.cantidad, 0);
  return <CartContext.Provider value={{ items, dispatch, total, totalItems }}>{children}</CartContext.Provider>;
}

function useCart() { const ctx = useContext(CartContext); if (!ctx) throw new Error('useCart requiere CartProvider'); return ctx; }

