interface Column<T> {
  key: keyof T;
  label: string;
  sortable?: boolean;
  render?: (value: any, row: T) => ReactNode;
}

interface DataTableProps<T> {
  columns: Column<T>[];
  data: T[];
  pageSize?: number;
}

function DataTable<T extends Record<string, any>>({ columns, data, pageSize = 10 }: DataTableProps<T>) {
  const [sortKey, setSortKey] = useState<keyof T | null>(null);
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [filter, setFilter] = useState('');
  const [page, setPage] = useState(1);

  const filtered = data.filter(row =>
    columns.some(col => String(row[col.key]).toLowerCase().includes(filter.toLowerCase()))
  );

  const sorted = sortKey
    ? [...filtered].sort((a, b) => {
        const cmp = String(a[sortKey]).localeCompare(String(b[sortKey]));
        return sortDir === 'asc' ? cmp : -cmp;
      })
    : filtered;

  const paginated = sorted.slice((page - 1) * pageSize, page * pageSize);
  const totalPages = Math.ceil(sorted.length / pageSize);

  return (
    <div>
      <input value={filter} onChange={e => { setFilter(e.target.value); setPage(1); }} placeholder="Filtrar..." />
      <table>
        <thead><tr>{columns.map(col => (
          <th key={String(col.key)} onClick={() => { setSortKey(col.key); setSortDir(d => d === 'asc' ? 'desc' : 'asc'); }}>
            {col.label} {sortKey === col.key ? (sortDir === 'asc' ? '↑' : '↓') : ''}
          </th>
        ))}</tr></thead>
        <tbody>{paginated.map((row, i) => (
          <tr key={i}>{columns.map(col => (
            <td key={String(col.key)}>{col.render ? col.render(row[col.key], row) : String(row[col.key])}</td>
          ))}</tr>
        ))}</tbody>
      </table>
      <div>Página {page}/{totalPages} <button disabled={page <= 1} onClick={() => setPage(p => p - 1)}>←</button> <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)}>→</button></div>
    </div>
  );
}

