function passwordsIguales(control: AbstractControl): ValidationErrors | null {
  const pass = control.get("password");
  const confirm = control.get("confirmPassword");
  if (!pass || !confirm) return null;
  return pass.value === confirm.value ? null : { passwordsNoIguales: true };
}

function emailDisponible(control: AbstractControl): Observable<ValidationErrors | null> {
  const emailsTomados = ["admin@test.com", "user@test.com"];
  return of(emailsTomados.includes(control.value)).pipe(
    delay(500),
    map(tomado => tomado ? { emailTomado: true } : null)
  );
}

