import { Injectable } from "@angular/core";
import { BehaviorSubject, Observable } from "rxjs";
import { map } from "rxjs/operators";

interface CartItem {
  productoId: number;
  nombre: string;
  precio: number;
  cantidad: number;
}

interface CartState {
  items: CartItem[];
}

@Injectable({ providedIn: "root" })
export class CartService {
  private state = new BehaviorSubject<CartState>({ items: [] });
  private state$ = this.state.asObservable();

  // Selectors
  items$: Observable<CartItem[]> = this.state$.pipe(map(s => s.items));
  total$: Observable<number> = this.state$.pipe(
    map(s => s.items.reduce((sum, i) => sum + i.precio * i.cantidad, 0))
  );
  cantidadItems$: Observable<number> = this.state$.pipe(
    map(s => s.items.reduce((sum, i) => sum + i.cantidad, 0))
  );

  private get currentState() { return this.state.value; }

  agregar(item: Omit<CartItem, "cantidad">) {
    const items = [...this.currentState.items];
    const existente = items.find(i => i.productoId === item.productoId);
    if (existente) {
      existente.cantidad++;
    } else {
      items.push({ ...item, cantidad: 1 });
    }
    this.state.next({ items });
  }

  eliminar(productoId: number) {
    this.state.next({
      items: this.currentState.items.filter(i => i.productoId !== productoId)
    });
  }

  actualizarCantidad(productoId: number, cantidad: number) {
    const items = this.currentState.items.map(i =>
      i.productoId === productoId ? { ...i, cantidad: Math.max(1, cantidad) } : i
    );
    this.state.next({ items });
  }

  vaciar() {
    this.state.next({ items: [] });
  }
}

