@Component({
  selector: "app-data-table",
  standalone: true,
  imports: [NgFor, NgClass],
  template: `
    <table class="data-table">
      <thead>
        <tr>
          <th *ngFor="let col of columns" (click)="sort(col.key)">
            {{ col.label }} {{ sortColumn === col.key ? (sortAsc ? "↑" : "↓") : "" }}
          </th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let item of paginatedItems">
          <td *ngFor="let col of columns">{{ item[col.key] }}</td>
        </tr>
      </tbody>
    </table>
    <div class="pagination">
      <button (click)="prevPage()" [disabled]="currentPage === 1">←</button>
      <span>{{ currentPage }} / {{ totalPages }}</span>
      <button (click)="nextPage()" [disabled]="currentPage === totalPages">→</button>
    </div>
  `
})
export class DataTableComponent<T> {
  @Input() items: T[] = [];
  @Input() columns: { key: keyof T; label: string }[] = [];
  @Input() pageSize = 10;
  @Output() pageChange = new EventEmitter<number>();

  currentPage = 1;
  sortColumn: keyof T | null = null;
  sortAsc = true;

  get totalPages(): number {
    return Math.ceil(this.items.length / this.pageSize);
  }

  get paginatedItems(): T[] {
    const start = (this.currentPage - 1) * this.pageSize;
    return this.sortedItems.slice(start, start + this.pageSize);
  }

  get sortedItems(): T[] {
    if (!this.sortColumn) return [...this.items];
    return [...this.items].sort((a, b) => {
      const valA = a[this.sortColumn!];
      const valB = b[this.sortColumn!];
      return this.sortAsc
        ? String(valA).localeCompare(String(valB))
        : String(valB).localeCompare(String(valA));
    });
  }

  sort(column: keyof T): void {
    if (this.sortColumn === column) { this.sortAsc = !this.sortAsc; }
    else { this.sortColumn = column; this.sortAsc = true; }
  }

  prevPage(): void { if (this.currentPage > 1) this.currentPage--; }
  nextPage(): void { if (this.currentPage < this.totalPages) this.currentPage++; }
}

