public class CalculadoraIMC {

    public static double calcularIMC(double peso, double altura) {
        if (altura <= 0) throw new IllegalArgumentException("Altura debe ser positiva");
        return peso / (altura * altura);
    }

    public static String clasificarIMC(double imc) {
        return switch {
            case _ when imc < 18.5 -> "Bajo peso";
            case _ when imc < 25 -> "Normal";
            case _ when imc < 30 -> "Sobrepeso";
            default -> "Obesidad";
        };
    }

    // Alternativa compatible:
    public static String clasificarIMCClassic(double imc) {
        if (imc < 18.5) return "Bajo peso";
        if (imc < 25) return "Normal";
        if (imc < 30) return "Sobrepeso";
        return "Obesidad";
    }

    public static void main(String[] args) {
        double peso = 70.5;
        double altura = 1.75;
        double imc = calcularIMC(peso, altura);
        System.out.printf("IMC: %.1f - Clasificación: %s%n", imc, clasificarIMC(imc));
    }
}

import java.util.Scanner;

public class GestorContactos {
    static final int MAX = 100;
    static String[] nombres = new String[MAX];
    static String[] telefonos = new String[MAX];
    static int cantidad = 0;

    public static void agregar(String nombre, String telefono) {
        if (cantidad >= MAX) {
            System.out.println("Agenda llena");
            return;
        }
        nombres[cantidad] = nombre;
        telefonos[cantidad] = telefono;
        cantidad++;
        System.out.println("Contacto agregado: " + nombre);
    }

    public static int buscar(String nombre) {
        for (int i = 0; i < cantidad; i++) {
            if (nombres[i].equalsIgnoreCase(nombre)) return i;
        }
        return -1;
    }

    public static void listar() {
        if (cantidad == 0) {
            System.out.println("No hay contactos");
            return;
        }
        for (int i = 0; i < cantidad; i++) {
            System.out.printf("%d. %s — %s%n", i + 1, nombres[i], telefonos[i]);
        }
    }

    public static void eliminar(String nombre) {
        int pos = buscar(nombre);
        if (pos == -1) {
            System.out.println("Contacto no encontrado");
            return;
        }
        for (int i = pos; i < cantidad - 1; i++) {
            nombres[i] = nombres[i + 1];
            telefonos[i] = telefonos[i + 1];
        }
        nombres[cantidad - 1] = null;
        telefonos[cantidad - 1] = null;
        cantidad--;
        System.out.println("Contacto eliminado");
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        agregar("Ana García", "555-1234");
        agregar("Carlos López", "555-5678");
        listar();
        int pos = buscar("Ana García");
        if (pos != -1) System.out.println("Teléfono: " + telefonos[pos]);
        eliminar("Ana García");
        listar();
    }
}

public abstract class Cuenta {
    private String numero;
    private double saldo;
    private String titular;

    public Cuenta(String numero, String titular, double saldoInicial) {
        this.numero = numero;
        this.titular = titular;
        this.saldo = saldoInicial;
    }

    public void depositar(double monto) {
        if (monto <= 0) throw new IllegalArgumentException("Monto debe ser positivo");
        saldo += monto;
    }

    public void retirar(double monto) {
        if (monto <= 0) throw new IllegalArgumentException("Monto debe ser positivo");
        if (monto > saldo) throw new IllegalArgumentException("Saldo insuficiente");
        saldo -= monto;
    }

    public abstract double calcularInteres();

    public double getSaldo() { return saldo; }
    protected void setSaldo(double saldo) { this.saldo = saldo; }
    public String getTitular() { return titular; }
    public String getNumero() { return numero; }
}

public class CuentaAhorro extends Cuenta {
    private double tasaInteres;

    public CuentaAhorro(String numero, String titular, double saldo, double tasaInteres) {
        super(numero, titular, saldo);
        this.tasaInteres = tasaInteres;
    }

    @Override
    public double calcularInteres() {
        return getSaldo() * tasaInteres;
    }

    public void aplicarInteres() {
        setSaldo(getSaldo() + calcularInteres());
    }
}

public class CuentaCorriente extends Cuenta {
    private double sobregiro;

    public CuentaCorriente(String numero, String titular, double saldo, double sobregiro) {
        super(numero, titular, saldo);
        this.sobregiro = sobregiro;
    }

    @Override
    public void retirar(double monto) {
        if (monto <= 0) throw new IllegalArgumentException("Monto debe ser positivo");
        if (monto > getSaldo() + sobregiro) throw new IllegalArgumentException("Excede sobregiro");
        setSaldo(getSaldo() - monto);
    }

    @Override
    public double calcularInteres() { return 0; }
}

