public interface Electrico {
    double getNivelBateria();
    void cargarBateria(double kwh);
}

public interface Alquilable {
    double calcularAlquiler(int dias);
    double calcularDeposito();
}

public class Coche extends Vehiculo implements Alquilable {
    private double consumoPorKm;

    public Coche(String marca, String modelo, int anio, double consumoPorKm) {
        super(marca, modelo, anio);
        this.consumoPorKm = consumoPorKm;
    }

    @Override public double calcularConsumo(double km) { return km * consumoPorKm; }
    @Override public double calcularAlquiler(int dias) { return dias * 45.0; }
    @Override public double calcularDeposito() { return 300.0; }
}

public class CocheElectrico extends Coche implements Electrico {
    private double bateria;
    private double capacidad;

    public CocheElectrico(String marca, String modelo, int anio, double capacidad) {
        super(marca, modelo, anio, 0.15);
        this.capacidad = capacidad;
        this.bateria = capacidad;
    }

    @Override public double getNivelBateria() { return (bateria / capacidad) * 100; }
    @Override public void cargarBateria(double kwh) { bateria = Math.min(capacidad, bateria + kwh); }
}

