import java.util.*;
import java.util.stream.*;

public class AnalizadorTexto {

    public static String limpiarTexto(String texto) {
        return texto.toLowerCase().replaceAll("[^a-záéíóúñü\\s]", "");
    }

    public static Map<String, Integer> frecuenciaPalabras(String texto) {
        Map<String, Integer> freq = new HashMap<>();
        String[] palabras = limpiarTexto(texto).split("\\s+");
        for (String p : palabras) {
            if (!p.isEmpty()) {
                freq.merge(p, 1, Integer::sum);
            }
        }
        return freq;
    }

    public static List<Map.Entry<String, Integer>> topPalabras(Map<String, Integer> freq, int n) {
        return freq.entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
            .limit(n)
            .collect(Collectors.toList());
    }

    public static Set<String> palabrasUnicas(String texto) {
        return new HashSet<>(Arrays.asList(limpiarTexto(texto).split("\\s+")));
    }

    public static void main(String[] args) {
        String texto = "Java es un lenguaje de programación. Java es popular y Java es poderoso.";
        var freq = frecuenciaPalabras(texto);
        System.out.println("Frecuencia: " + freq);
        System.out.println("Top 3: " + topPalabras(freq, 3));
        System.out.println("Únicas: " + palabrasUnicas(texto));
    }
}

class EstudianteNoEncontradoException extends Exception {
