}

class CalificacionInvalidaException extends RuntimeException {
    public CalificacionInvalidaException(String msg) { super(msg); }
}

class Estudiante {
    private String id;
    private String nombre;
    private List<Double> calificaciones;

    public Estudiante(String id, String nombre) {
        this.id = id;
        this.nombre = nombre;
        this.calificaciones = new ArrayList<>();
    }

    public void agregarCalificacion(double nota) {
        if (nota < 0 || nota > 10) throw new CalificacionInvalidaException("Nota: " + nota);
        calificaciones.add(nota);
    }

    public double getPromedio() {
        return calificaciones.stream().mapToDouble(Double::doubleValue).average().orElse(0);
    }

    public String getId() { return id; }
    public String getNombre() { return nombre; }
}

class SistemaEstudiantes {
    private Map<String, Estudiante> estudiantes = new LinkedHashMap<>();

    public void agregar(Estudiante e) { estudiantes.put(e.getId(), e); }

    public Estudiante buscar(String id) throws EstudianteNoEncontradoException {
        Estudiante e = estudiantes.get(id);
        if (e == null) throw new EstudianteNoEncontradoException("ID: " + id);
        return e;
    }

    public double promedioGeneral() {
        return estudiantes.values().stream()
            .mapToDouble(Estudiante::getPromedio)
            .average().orElse(0);
    }

    public List<Estudiante> listarPorPromedio() {
        return estudiantes.values().stream()
            .sorted(Comparator.comparingDouble(Estudiante::getPromedio).reversed())
            .collect(Collectors.toList());
    }
}

