import java.time.LocalDate;
import java.util.*;
import java.util.stream.*;

record LineaPedido(String producto, int cantidad, double precioUnitario) {
    public double subtotal() { return cantidad * precioUnitario; }
}

record Pedido(String id, String cliente, List<LineaPedido> lineas, LocalDate fecha, String estado) {
    public double total() {
        return lineas.stream().mapToDouble(LineaPedido::subtotal).sum();
    }
}

class AnalisisPedidos {

    public static double totalPedido(Pedido p) { return p.total(); }

    public static String productoMasVendido(List<Pedido> pedidos) {
        return pedidos.stream()
            .flatMap(p -> p.lineas().stream())
            .collect(Collectors.groupingBy(
                LineaPedido::producto,
                Collectors.summingInt(LineaPedido::cantidad)
            ))
            .entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse("Sin datos");
    }

    public static List<Pedido> pedidosUltimoMes(List<Pedido> pedidos) {
        LocalDate haceUnMes = LocalDate.now().minusMonths(1);
        return pedidos.stream()
            .filter(p -> p.fecha().isAfter(haceUnMes))
            .collect(Collectors.toList());
    }

    public static List<String> clientesVIP(List<Pedido> pedidos, double minimo) {
        return pedidos.stream()
            .collect(Collectors.groupingBy(
                Pedido::cliente,
                Collectors.summingDouble(Pedido::total)
            ))
            .entrySet().stream()
            .filter(e -> e.getValue() > minimo)
            .map(Map.Entry::getKey)
            .collect(Collectors.toList());
    }

    public static DoubleSummaryStatistics estadisticas(List<Pedido> pedidos) {
        return pedidos.stream()
            .mapToDouble(Pedido::total)
            .summaryStatistics();
    }
}

