    private Set<String> taskNames = new HashSet<>();

    public void addTask(String category, Task task) {
        if (taskNames.add(task.getName())) {
            tasksByCategory.computeIfAbsent(category, k -> new ArrayList<>()).add(task);
        }
    }

    public List<Task> getSortedByPriority(String category) {
