public class InvalidEmailException extends RuntimeException {
    public InvalidEmailException(String email) {
        super("Email inválido: " + email);
    }
}

public class UserValidator {
    private Set<String> registeredEmails = new HashSet<>();

    public void validate(String email, String password) {
        if (!email.matches("^[A-Za-z0-9+_.-]+@(.+)$")) {
            throw new InvalidEmailException(email);
        }
        if (password.length() < 8 || !password.matches(".*[A-Z].*")) {
            throw new WeakPasswordException();
        }
        if (registeredEmails.contains(email)) {
            throw new DuplicateUserException(email);
        }
        registeredEmails.add(email);
    }
}

public class ArchivoNoEncontradoException extends RuntimeException {
    public ArchivoNoEncontradoException(String ruta) {
        super("Archivo no encontrado: " + ruta);
    }
}

public class FileManager {
    public String leerArchivo(String ruta) {
        try (BufferedReader reader = new BufferedReader(new FileReader(ruta))) {
            StringBuilder sb = new StringBuilder();
            String linea;
            while ((linea = reader.readLine()) != null) {
                sb.append(linea).append("\n");
            }
            return sb.toString();
        } catch (FileNotFoundException e) {
            throw new ArchivoNoEncontradoException(ruta);
        } catch (IOException e) {
            throw new RuntimeException("Error al leer: " + ruta, e);
        }
    }

    public void escribirArchivo(String ruta, String contenido) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(ruta))) {
            writer.write(contenido);
        } catch (IOException e) {
            throw new RuntimeException("Error al escribir: " + ruta, e);
        }
    }

    public void copiarArchivo(String origen, String destino) {
        String contenido = leerArchivo(origen);
        escribirArchivo(destino, contenido);
    }
}

