def agregar_producto(inventario: dict, id: str, nombre: str, precio: float, stock: int, categoria: str) -> None:
    inventario[id] = {
        "nombre": nombre,
        "precio": precio,
        "stock": stock,
        "categoria": categoria
    }

def actualizar_stock(inventario: dict, id: str, cantidad: int) -> bool:
    if id not in inventario:
        return False
    inventario[id]["stock"] += cantidad
    return True

def buscar_por_nombre(inventario: dict, termino: str) -> list[dict]:
    termino = termino.lower()
    return [
        {"id": k, **v}
        for k, v in inventario.items()
        if termino in v["nombre"].lower()
    ]

def valor_total(inventario: dict) -> float:
    return sum(p["precio"] * p["stock"] for p in inventario.values())

def stock_bajo(inventario: dict, limite: int = 5) -> list[dict]:
    return [
        {"id": k, **v}
        for k, v in inventario.items()
        if v["stock"] < limite
    ]

def resumen_por_categoria(inventario: dict) -> dict[str, dict]:
    categorias: dict[str, dict] = {}
    for p in inventario.values():
        cat = p["categoria"]
        if cat not in categorias:
            categorias[cat] = {"productos": 0, "valor_total": 0.0}
        categorias[cat]["productos"] += 1
        categorias[cat]["valor_total"] += p["precio"] * p["stock"]
    return categorias


