from abc import ABC, abstractmethod
from dataclasses import dataclass, field


class Cuenta(ABC):
    def __init__(self, numero: str, titular: str, saldo: float = 0):
        self.numero = numero
        self.titular = titular
        self._saldo = saldo

    @property
    def saldo(self) -> float:
        return self._saldo

    def depositar(self, monto: float) -> None:
        if monto <= 0:
            raise ValueError("Monto debe ser positivo")
        self._saldo += monto

    @abstractmethod
    def retirar(self, monto: float) -> None: ...

    @abstractmethod
    def calcular_interes(self) -> float: ...

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(numero={self.numero}, saldo={self._saldo:.2f})"


class CuentaAhorro(Cuenta):
    def __init__(self, numero: str, titular: str, saldo: float, tasa: float = 0.03):
        super().__init__(numero, titular, saldo)
        self.tasa = tasa

    def retirar(self, monto: float) -> None:
        if monto > self._saldo:
            raise ValueError("Saldo insuficiente")
        self._saldo -= monto

    def calcular_interes(self) -> float:
        return self._saldo * self.tasa

    def aplicar_interes(self) -> None:
        self._saldo += self.calcular_interes()


class CuentaCorriente(Cuenta):
    def __init__(self, numero: str, titular: str, saldo: float, sobregiro: float = 500):
        super().__init__(numero, titular, saldo)
        self.sobregiro = sobregiro

    def retirar(self, monto: float) -> None:
        if monto > self._saldo + self.sobregiro:
            raise ValueError("Excede límite de sobregiro")
        self._saldo -= monto

    def calcular_interes(self) -> float:
        return 0.0


@dataclass
class Cliente:
    nombre: str
    dni: str
    cuentas: list[Cuenta] = field(default_factory=list)

    def saldo_total(self) -> float:
        return sum(c.saldo for c in self.cuentas)

    def agregar_cuenta(self, cuenta: Cuenta) -> None:
        self.cuentas.append(cuenta)

    def __str__(self) -> str:
        return f"Cliente({self.nombre}, cuentas={len(self.cuentas)}, total=${self.saldo_total():,.2f})"

