class Biblioteca:
    def __init__(self, nombre: str):
        self.nombre = nombre
        self._catalogo: list[Publicacion] = []

    def agregar(self, pub: Publicacion) -> None:
        self._catalogo.append(pub)

    def filtrar_por_tipo(self, tipo: str) -> list[Publicacion]:
        return [p for p in self._catalogo if p.tipo() == tipo]

    # Dunder methods — protocolos
    def __len__(self) -> int:
        return len(self._catalogo)

    def __contains__(self, item: Publicacion) -> bool:
        return item in self._catalogo

    def __getitem__(self, index: int) -> Publicacion:
        return self._catalogo[index]

    def __iter__(self):
        return iter(self._catalogo)

    def __add__(self, other: "Biblioteca") -> "Biblioteca":
        nueva = Biblioteca(f"{self.nombre} + {other.nombre}")
        nueva._catalogo = self._catalogo + other._catalogo
        return nueva

    def __repr__(self) -> str:
        return f"Biblioteca('{self.nombre}', {len(self)} items)"

import time
from functools import wraps
from collections import defaultdict


def cache(func):
    """Decorador de caché simple basado en argumentos."""
    _cache: dict = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in _cache:
            _cache[key] = func(*args, **kwargs)
        return _cache[key]

    wrapper.cache = _cache
    wrapper.cache_clear = lambda: _cache.clear()
    return wrapper


def rate_limit(max_calls: int, period: float = 1.0):
    """Limita la frecuencia de llamadas a una función."""
    def decorador(func):
        timestamps: list[float] = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            ahora = time.time()
            # Limpiar timestamps fuera del periodo
            timestamps[:] = [t for t in timestamps if ahora - t < period]

            if len(timestamps) >= max_calls:
                espera = period - (ahora - timestamps[0])
                if espera > 0:
                    time.sleep(espera)

            timestamps.append(time.time())
            return func(*args, **kwargs)

        return wrapper
    return decorador


