from collections import defaultdict
from typing import Generator
import re


def leer_lineas(archivo: str) -> Generator[str, None, None]:
    """Lee un archivo línea por línea (lazy)."""
    with open(archivo, "r", encoding="utf-8") as f:
        for linea in f:
            yield linea.strip()


def filtrar_errores(lineas: Generator[str, None, None]) -> Generator[str, None, None]:
    """Filtra solo líneas que contienen ERROR o WARN."""
    for linea in lineas:
        if "ERROR" in linea or "WARN" in linea:
            yield linea


def parsear_log(lineas: Generator[str, None, None]) -> Generator[dict, None, None]:
    """Extrae campos estructurados de cada línea."""
    patron = re.compile(
        r"(?P<fecha>\d{4}-\d{2}-\d{2}).*?"
        r"(?P<nivel>ERROR|WARN).*?"
        r"(?P<codigo>\d{3}).*?"
        r"(?P<mensaje>.+)"
    )
    for linea in lineas:
        match = patron.search(linea)
        if match:
            yield match.groupdict()


def agrupar_por_codigo(
    logs: Generator[dict, None, None]
) -> dict[str, list[dict]]:
    """Agrupa logs por código de error."""
    grupos: dict[str, list[dict]] = defaultdict(list)
    for log in logs:
        grupos[log["codigo"]].append(log)
    return dict(grupos)


def generar_reporte(grupos: dict[str, list[dict]]) -> str:
    """Genera un reporte resumen."""
    lineas = ["REPORTE DE ERRORES", "=" * 40]
    for codigo, logs in sorted(grupos.items(), key=lambda x: -len(x[1])):
        lineas.append(f"\nCódigo {codigo}: {len(logs)} ocurrencias")
        for log in logs[:3]:  # mostrar primeros 3
            lineas.append(f"  [{log['fecha']}] {log['mensaje'][:60]}")
        if len(logs) > 3:
            lineas.append(f"  ... y {len(logs) - 3} más")
    return "\n".join(lineas)


# Pipeline encadenado
reporte = generar_reporte(
    agrupar_por_codigo(
        parsear_log(
            filtrar_errores(
                leer_lineas("app.log")
            )
        )
    )
)
print(reporte)

import csv
import json
import logging
from pathlib import Path
from dataclasses import dataclass
from typing import Any

logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
logger = logging.getLogger(__name__)


@dataclass
class ResultadoConversion:
    validas: list[dict[str, Any]]
    errores: list[dict[str, str]]


def validar_fila(fila: dict, campos_requeridos: list[str]) -> list[str]:
    """Retorna lista de errores para una fila."""
    errores = []
    for campo in campos_requeridos:
        if not fila.get(campo, "").strip():
            errores.append(f"Campo vacío: {campo}")
    if "edad" in fila:
        try:
            edad = int(fila["edad"])
            if edad < 0 or edad > 150:
                errores.append(f"Edad inválida: {edad}")
        except ValueError:
            errores.append(f"Edad no numérica: {fila['edad']}")
    if "email" in fila and "@" not in fila.get("email", ""):
        errores.append(f"Email inválido: {fila['email']}")
    return errores


def csv_a_json(ruta_csv: Path, ruta_json: Path, campos_requeridos: list[str]) -> ResultadoConversion:
    """Convierte CSV a JSON con validación."""
    resultado = ResultadoConversion(validas=[], errores=[])

    try:
        with ruta_csv.open("r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for i, fila in enumerate(reader, start=2):  # start=2 por header
                errores = validar_fila(fila, campos_requeridos)
                if errores:
                    resultado.errores.append({"fila": str(i), "errores": "; ".join(errores)})
                    logger.warning("Fila %d: %s", i, "; ".join(errores))
                else:
                    # Convertir tipos
                    if "edad" in fila:
                        fila["edad"] = int(fila["edad"])
                    resultado.validas.append(fila)

        with ruta_json.open("w", encoding="utf-8") as f:
            json.dump(resultado.validas, f, indent=2, ensure_ascii=False)

        logger.info("Convertidas %d filas, %d errores", len(resultado.validas), len(resultado.errores))

    except FileNotFoundError:
        logger.error("Archivo no encontrado: %s", ruta_csv)
        raise

    return resultado

import jwt
from datetime import datetime, timedelta, timezone
from functools import wraps
from flask import request, jsonify, current_app


def generar_token(user_id: int, rol: str) -> str:
    payload = {
        "sub": user_id,
        "rol": rol,
        "iat": datetime.now(timezone.utc),
        "exp": datetime.now(timezone.utc) + timedelta(hours=8)
    }
    return jwt.encode(payload, current_app.config["SECRET_KEY"], algorithm="HS256")


def verificar_token(token: str) -> dict:
    try:
        return jwt.decode(token, current_app.config["SECRET_KEY"], algorithms=["HS256"])
    except jwt.ExpiredSignatureError:
        raise ValueError("Token expirado")
    except jwt.InvalidTokenError:
        raise ValueError("Token inválido")


def jwt_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization")
        if not auth_header or not auth_header.startswith("Bearer "):
            return jsonify({"error": "Token requerido"}), 401

        token = auth_header.split(" ")[1]
        try:
            payload = verificar_token(token)
        except ValueError as e:
            return jsonify({"error": str(e)}), 401

        request.current_user = payload
        return f(*args, **kwargs)
    return decorated


def rol_required(rol: str):
    def decorator(f):
        @wraps(f)
        @jwt_required
        def decorated(*args, **kwargs):
            if request.current_user.get("rol") != rol:
                return jsonify({"error": "Permiso denegado"}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator


