from abc import ABC, abstractmethod

class Empleado(ABC):
    def __init__(self, nombre, apellido):
        self.nombre = nombre
        self.apellido = apellido

    @abstractmethod
    def calcular_salario(self) -> float:
        pass

    def __str__(self):
        return f"{self.nombre} {self.apellido}"

    def __repr__(self):
        return f"{self.__class__.__name__}('{self.nombre}', '{self.apellido}')"

class EmpleadoFijo(Empleado):
    def __init__(self, nombre, apellido, salario_mensual):
        super().__init__(nombre, apellido)
        self.salario_mensual = salario_mensual

    def calcular_salario(self) -> float:
        return self.salario_mensual

class EmpleadoPorHora(Empleado):
    def __init__(self, nombre, apellido, tarifa, horas):
        super().__init__(nombre, apellido)
        self.tarifa = tarifa
        self.horas = horas

    def calcular_salario(self) -> float:
        return self.tarifa * self.horas

from abc import ABC, abstractmethod

class Vehiculo(ABC):
    def __init__(self, marca: str, modelo: str, anio: int):
        self.marca = marca
        self.modelo = modelo
        self.anio = anio

    @abstractmethod
    def calcular_consumo(self, km: float) -> float: ...

    def info(self) -> str:
        return f"{self.marca} {self.modelo} ({self.anio})"

class Electrico(ABC):
    @abstractmethod
    def cargar_bateria(self, kwh: float) -> None: ...

    @abstractmethod
    def nivel_bateria(self) -> float: ...

class Alquilable(ABC):
    @abstractmethod
    def calcular_alquiler(self, dias: int) -> float: ...

class Coche(Vehiculo, Alquilable):
    def calcular_consumo(self, km: float) -> float:
        return km * 0.07

    def calcular_alquiler(self, dias: int) -> float:
        return dias * 45.0

class CocheElectrico(Coche, Electrico):
    def __init__(self, marca, modelo, anio, capacidad: float):
        super().__init__(marca, modelo, anio)
        self._bateria = capacidad
        self.capacidad = capacidad

    def calcular_consumo(self, km: float) -> float:
        return km * 0.015

    def cargar_bateria(self, kwh: float) -> None:
        self._bateria = min(self.capacidad, self._bateria + kwh)

    def nivel_bateria(self) -> float:
        return (self._bateria / self.capacidad) * 100

import csv

def procesar_csv(ruta, campos_requeridos):
    try:
        with open(ruta, newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            resultados = []
            for i, fila in enumerate(reader, 1):
                faltantes = [c for c in campos_requeridos if c not in fila or not fila[c]]
                if faltantes:
                    raise ValueError(f'Fila {i}: faltan campos {faltantes}')
                resultados.append(dict(fila))
            return resultados
    except FileNotFoundError:
        raise FileNotFoundError(f'Archivo no encontrado: {ruta}')

