public class FacturaService
{
    public (double Total, double Impuesto, double Descuento) Calcular(
        double subtotal, double impuesto = 0.16, double descuento = 0)
    {
        if (subtotal < 0) throw new ArgumentException("Subtotal negativo");
        double descuentoCalculado = subtotal * descuento;
        double baseImponible = subtotal - descuentoCalculado;
        double impuestoCalculado = baseImponible * impuesto;
        double total = baseImponible + impuestoCalculado;

        return (Math.Round(total, 2), Math.Round(impuestoCalculado, 2), Math.Round(descuentoCalculado, 2));
    }

    public string GenerarResumen(double subtotal, double impuesto = 0.16, double descuento = 0)
    {
        var f = Calcular(subtotal, impuesto, descuento);
        return $"Subtotal: {subtotal:C}\nDescuento: {f.Descuento:C}\nImpuesto: {f.Impuesto:C}\nTotal: {f.Total:C}";
    }
}

