public record Contacto(string Nombre, string Telefono, string Email);

public class GestorContactos
{
    private List<Contacto> contactos = new();

    public void Agregar(Contacto c)
    {
        if (string.IsNullOrWhiteSpace(c.Nombre))
            throw new ArgumentException("Nombre vacío");
        contactos.Add(c);
    }

    public Contacto? BuscarPorNombre(string nombre) =>
        contactos.FirstOrDefault(c => c.Nombre.Equals(nombre, StringComparison.OrdinalIgnoreCase));

    public bool Eliminar(string nombre)
    {
        var contacto = BuscarPorNombre(nombre);
        return contacto is not null && contactos.Remove(contacto);
    }

    public Dictionary<char, List<Contacto>> AgruparPorLetra() =>
        contactos
            .OrderBy(c => c.Nombre)
            .GroupBy(c => char.ToUpper(c.Nombre[0]))
            .ToDictionary(g => g.Key, g => g.ToList());

    public List<Contacto> Buscar(string termino) =>
        contactos.Where(c =>
            c.Nombre.Contains(termino, StringComparison.OrdinalIgnoreCase) ||
            c.Email.Contains(termino, StringComparison.OrdinalIgnoreCase)
        ).ToList();

    public void ListarAgrupado()
    {
        foreach (var grupo in AgruparPorLetra())
        {
            Console.WriteLine($"=== {grupo.Key} ===");
            foreach (var c in grupo.Value)
                Console.WriteLine($"  {c.Nombre} — {c.Telefono}");
        }
    }
}

