public class BibliotecaService
{
    private List<Prestamo> prestamos = new();

    public Prestamo Prestar(Libro libro, Usuario usuario)
    {
        if (EstaPrestado(libro))
            throw new InvalidOperationException($"Libro ya prestado: {libro.Titulo}");
        var prestamo = new Prestamo(libro, usuario);
        prestamos.Add(prestamo);
        usuario.Prestamos.Add(prestamo);
        return prestamo;
    }

    public bool EstaPrestado(Libro libro) =>
        prestamos.Any(p => p.Libro.ISBN == libro.ISBN && p.Activo);

    public List<Libro> LibrosDisponibles(List<Libro> catalogo) =>
        catalogo.Where(l => !EstaPrestado(l)).ToList();

    public List<Prestamo> PrestamosPorUsuario(Usuario u) =>
        u.Prestamos.OrderByDescending(p => p.FechaPrestamo).ToList();

    public List<(string Titulo, int Cantidad)> LibrosMasPrestados() =>
        prestamos
            .GroupBy(p => p.Libro.Titulo)
            .Select(g => (Titulo: g.Key, Cantidad: g.Count()))
            .OrderByDescending(x => x.Cantidad)
            .Take(5)
            .ToList();

    public int PrestamosActivos => prestamos.Count(p => p.Activo);
}

