public async Task<List<string>> FetchAllAsync(
    List<string> urls, CancellationToken ct = default) {
    var tasks = urls.Select(url => FetchWithTimeoutAsync(url, ct));
    var results = await Task.WhenAll(tasks);
    return results.Where(r => r != null).ToList();
}

private async Task<string> FetchWithTimeoutAsync(
    string url, CancellationToken ct) {
    try {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(TimeSpan.FromSeconds(10));
        return await httpClient.GetStringAsync(url, cts.Token);
    } catch {
        return null;
    }
}

public class FileProcessor {
    private readonly SemaphoreSlim _semaphore = new(3);

    public async Task<Dictionary<string, int>> ProcessFilesAsync(
        List<string> filePaths, IProgress<int> progress, CancellationToken ct) {
        var results = new Dictionary<string, int>();
        int completed = 0;

        var tasks = filePaths.Select(async path => {
            await _semaphore.WaitAsync(ct);
            try {
                int lineCount = 0;
                var lines = await File.ReadAllLinesAsync(path, ct);
                foreach (var line in lines) {
                    // procesar línea
                    lineCount++;
                }
                lock (results) { results[path] = lineCount; }
                Interlocked.Increment(ref completed);
                progress?.Report(completed * 100 / filePaths.Count);
            } finally {
                _semaphore.Release();
            }
        });

        await Task.WhenAll(tasks);
        return results;
    }
}

