// Application/Services/CalificacionService.cs
public class CalificacionService : ICalificacionService
{
    private readonly ICalificacionRepository _repo;

    public CalificacionService(ICalificacionRepository repo) => _repo = repo;

    public async Task<CalificacionDTO> RegistrarAsync(CrearCalificacionDTO dto)
    {
        var calificacion = new Calificacion
        {
            AlumnoId = dto.AlumnoId,
            MateriaId = dto.MateriaId,
            Parcial1 = dto.Parcial1,
            Parcial2 = dto.Parcial2,
            Parcial3 = dto.Parcial3,
            Final = CalcularFinal(dto.Parcial1, dto.Parcial2, dto.Parcial3)
        };
        var creado = await _repo.AddAsync(calificacion);
        return MapToDTO(creado);
    }

    private double CalcularFinal(double p1, double p2, double p3) => (p1 + p2 + p3) / 3.0;

    public async Task<IEnumerable<ReporteDTO>> GetReportePromediosAsync(int grupoId)
    {
        var calificaciones = await _repo.GetByGrupoAsync(grupoId);
        return calificaciones.GroupBy(c => new { c.Alumno.Nombre, c.Materia.Nombre })
            .Select(g => new ReporteDTO(
                g.Key.Nombre, g.Key.Nombre, g.Average(c => c.Final),
                g.Average(c => c.Final) >= 6.0 ? "Aprobado" : "Reprobado", ""
            ));
    }
}

