// ReporteService con LINQ
public class ReporteService : IReporteService
{
    private readonly ICalificacionRepository _calRepo;

    public async Task<IEnumerable<ReporteDTO>> GetReprobadosAsync(int grupoId)
    {
        var calificaciones = await _calRepo.GetByGrupoAsync(grupoId);
        return calificaciones
            .Where(c => c.Final < 6.0)
            .GroupBy(c => new { c.Alumno.Nombre, c.Materia.Nombre })
            .Select(g => new ReporteDTO(
                g.Key.Nombre, g.Key.Nombre, g.Average(c => c.Final),
                "Reprobado", c.Materia.Profesor.Nombre
            ));
    }

    public async Task<EstadisticasDTO> GetEstadisticasAsync(int materiaId)
    {
        var calificaciones = await _calRepo.GetByMateriaAsync(materiaId);
        var finales = calificaciones.Select(c => c.Final).ToList();
        return new EstadisticasDTO(
            Promedio: finales.Average(),
            Minimo: finales.Min(),
            Maximo: finales.Max(),
            Aprobados: finales.Count(f => f >= 6.0),
            Reprobados: finales.Count(f => f < 6.0),
            TasaAprobacion: (double)finales.Count(f => f >= 6.0) / finales.Count() * 100
        );
    }
}

